    //| echo: true
    //| output: true

    mm::Image lab = mm::label0(img_final, mm::sebox());

    // Trouver la valeur maximale (nombre de composantes)
    int n = 0;
    for (unsigned char v : lab.data) {
        if (v &gt; n) n = v;
